 SigninUi signin;protected Store store;protected String platform="chaoxing",aid="",task="",section="章节";protected JSONObject account;LinearLayout root,body;TextView notice;WebView web;Handler timer=new Handler(Looper.getMainLooper());ExecutorService worker=Executors.newSingleThreadExecutor();boolean alive=true,asking;String page="学习",pendingExport="";ValueCallback<Uri[]> fileCallback;android.webkit.GeolocationPermissions.Callback geoCallback;String geoOrigin;
