 protected void onCreate(Bundle b){super.onCreate(b);store=new Store(this);platform=getIntent().getStringExtra("platform");if(platform==null)platform=store.setting("_global","platform","chaoxing");try{if(slotIndex()>=0){aid=getIntent().getStringExtra("account");account=store.account(aid);if(account.getInt("slot")!=slotIndex())throw new Exception("账号空间不匹配");platform=account.getString("platform");if(!Profile.bound){WebView.setDataDirectorySuffix("account-"+aid);Profile.bound=true;Profile.account=aid;}else if(!aid.equals(Profile.account))throw new Exception("账号会话需要重新打开");}else aid=store.setting("_global","selected:"+platform,"");}catch(Exception e){aid="";account=null;}getWindow().setStatusBarColor(0xff1d273b);getWindow().setNavigationBarColor(0xff1d273b);signin=new SigninUi(this);if(getIntent().hasExtra("openPage"))page=getIntent().getStringExtra("openPage");render();handleTaskIntent();timer.postDelayed(tick,1500);}
