 int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}LinearLayout col(){LinearLayout p=new LinearLayout(this);p.setOrientation(1);return p;}LinearLayout row(){LinearLayout p=new LinearLayout(this);p.setOrientation(0);return p;}
