 Button button(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setTextSize(13);b.setAllCaps(false);b.setTextColor(0xff27568d);android.graphics.drawable.GradientDrawable bg=new android.graphics.drawable.GradientDrawable();boolean selected=(s.equals("学习通")&&platform.equals("chaoxing"))||(s.equals("雨课堂")&&platform.equals("yuketang"))||s.equals(page);bg.setColor(selected?0xff316de6:0xffffffff);bg.setCornerRadius(dp(9));bg.setStroke(dp(1),0xffd8dfeb);b.setBackground(bg);if(selected)b.setTextColor(0xffffffff);b.setStateListAnimator(null);b.setPadding(dp(5),dp(6),dp(5),dp(6));b.setMinHeight(dp(38));b.setOnClickListener(v->{try{r.run();}catch(Exception e){message(e.getMessage());}});return b;}
